\title{The Coloring--Independence Bound and the Independence Ratio of Unit-Distance Graphs}
\author{Aristotle}
\date{July 1, 2026}

\begin{document}

\begin{abstract}
We study the \emph{independence ratio} $\alpha(G)/|V(G)|$ of finite graphs, with
particular attention to unit-distance graphs in the Euclidean plane. We prove a
sharp, elementary bound linking colorability to independence: every finite graph
admitting a proper $k$-coloring contains an independent set $S$ with
$|V(G)| \le k\,|S|$, so its independence ratio is at least $1/k$. Specializing to
$k=4$ yields a rigorous quarter bound for every four-colorable graph, including
every four-colorable planar unit-distance graph. We show the bound is best
possible via the complete graph $K_k$, whose independence ratio is exactly $1/k$,
and we anchor the theory with an explicit planar witness: the unit equilateral
triangle, whose unit-distance graph is $K_3$ and whose independence ratio is
exactly $1/3 > 1/4$. Crucially, we delineate the boundary between theorem and
conjecture: the unconditional claim that all planar unit-distance graphs have
independence ratio at least $1/4$ does \emph{not} follow from colorability, since
the plane contains five-chromatic unit-distance configurations (de Grey, 2018)
and the best known lower bounds for the plane's independence ratio lie below
$1/4$. We close with a program of conjectures.
\end{abstract}

\maketitle

\section{Introduction}

A \emph{unit-distance graph} in the plane is a graph whose vertices are points of
$\mathbb{R}^2$ and whose edges join precisely those pairs at Euclidean distance
exactly $1$. These graphs are the natural setting of the Hadwiger--Nelson problem
on the chromatic number of the plane.

For a graph $G=(V,E)$, the \emph{independence number} $\alpha(G)$ is the size of
the largest set of pairwise non-adjacent vertices, and the \emph{independence
ratio} is $\rho(G) := \alpha(G)/|V(G)| \in (0,1]$. A folklore assertion holds
that $\rho(G) \ge 1/4$ for every finite planar unit-distance graph. We isolate
and prove the rigorous core underlying this intuition---a sharp bound
$\rho(G) \ge 1/k$ for every $k$-colorable graph---and identify exactly where the
unconditional planar claim ceases to be a theorem.

\section{Definitions}

Throughout, $G=(V,E)$ is a finite simple graph with $|V|=n$.

\begin{definition}[Independent set]
A set $S \subseteq V$ is \emph{independent} if no two distinct vertices of $S$
are adjacent.
\end{definition}

\begin{definition}[Independence number and ratio]
$\alpha(G) = \max\{|S| : S \text{ independent}\}$ and $\rho(G) = \alpha(G)/n$.
\end{definition}

\begin{definition}[Proper coloring]
A \emph{proper $k$-coloring} is a map $C : V \to \{1,\dots,k\}$ with
$C(u) \ne C(v)$ whenever $\{u,v\} \in E$. The graph is \emph{$k$-colorable} if
such $C$ exists; the chromatic number $\chi(G)$ is the least such $k$.
\end{definition}

\begin{definition}[Color class]
For a coloring $C$ and color $c$, the color class is
$V_c = \{v : C(v)=c\}$. Each $V_c$ is independent.
\end{definition}

\begin{definition}[Unit-distance graph]
Given a finite family of points $p : I \to \mathbb{R}^2$, the unit-distance
graph $U(p)$ has vertex set $I$, with $i$ adjacent to $j$ iff $i \ne j$ and
$\dist(p_i,p_j)=1$.
\end{definition}

\section{The Coloring--Independence Engine}

\begin{lemma}[Large color class]\label{lem:large}
Let $G$ have $n$ vertices and let $C$ be a proper $k$-coloring with $k \ge 1$.
Then some color $c$ satisfies $n \le k\,|V_c|$, i.e.\ $|V_c| \ge n/k$.
\end{lemma}

\begin{proof}
The classes $V_1,\dots,V_k$ partition $V$, so $\sum_{c=1}^k |V_c| = n$. If every
class had $|V_c| < n/k$, then $n = \sum_c |V_c| < k\cdot(n/k) = n$, a
contradiction. Hence some class satisfies $|V_c| \ge n/k$.
\end{proof}

\begin{theorem}[Coloring--Independence Bound]\label{thm:main}
If $G$ on $n$ vertices is $k$-colorable with $k \ge 1$, then $G$ contains an
independent set $S$ with $n \le k\,|S|$, hence $\rho(G) \ge 1/k$.
\end{theorem}

\begin{proof}
Fix a proper $k$-coloring $C$ and, by Lemma~\ref{lem:large}, a color $c$ with
$|V_c| \ge n/k$. The class $S := V_c$ is independent and $n \le k\,|S|$. Dividing
by $n>0$ gives $\alpha(G)/n \ge |S|/n \ge 1/k$.
\end{proof}

Equivalently, $\rho(G) \ge 1/\chi(G)$.

\section{The Quarter Bound}

\begin{theorem}[Quarter bound]\label{thm:quarter}
Every four-colorable finite graph $G$ contains an independent set $S$ with
$|V(G)| \le 4\,|S|$; equivalently $\rho(G) \ge 1/4$. In particular this holds for
every four-colorable planar unit-distance graph.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:main} with $k=4$.
\end{proof}

\section{Sharpness}

\begin{theorem}[Tightness]\label{thm:tight}
For every $k \ge 1$, the complete graph $K_k$ is $k$-colorable with
$\rho(K_k)=1/k$ exactly. Hence Theorem~\ref{thm:main} is best possible.
\end{theorem}

\begin{proof}
$K_k$ has $k$ pairwise-adjacent vertices; distinct colors on each vertex give a
proper $k$-coloring. Since every pair is adjacent, $\alpha(K_k)=1$, so
$\rho(K_k)=1/k$, achieving equality in Theorem~\ref{thm:main}.
\end{proof}

\section{An Explicit Planar Witness}

\begin{construction}\label{con:tri}
Let $p_0=(0,0)$, $p_1=(1,0)$, $p_2=\bigl(\tfrac12,\tfrac{\sqrt3}{2}\bigr)$.
\end{construction}

\begin{lemma}[All pairwise distances are one]\label{lem:dist}
For all distinct $i,j$, $\dist(p_i,p_j)=1$.
\end{lemma}

\begin{proof}
$\|p_0-p_1\|=1$; and $\|p_0-p_2\|^2 = \tfrac14+\tfrac34 = 1$ since
$(\sqrt3/2)^2=3/4$; symmetrically $\|p_1-p_2\|^2 = \tfrac14+\tfrac34 = 1$.
\end{proof}

\begin{proposition}[The triangle is $K_3$]\label{prop:k3}
The unit-distance graph $U(p)$ of Construction~\ref{con:tri} has vertices
adjacent iff distinct; that is, $U(p)=K_3$.
\end{proposition}

\begin{proof}
Adjacency requires $i \ne j$ and $\dist(p_i,p_j)=1$; by Lemma~\ref{lem:dist} the
distance condition is automatic for distinct vertices.
\end{proof}

\begin{corollary}\label{cor:apply}
$U(p)$ is $3$-colorable, hence $4$-colorable, so by
Theorem~\ref{thm:quarter} it has an independent set of relative size at least
$1/4$.
\end{corollary}

\begin{theorem}[Exact ratio of the triangle]\label{thm:third}
The independence ratio of $U(p)$ is exactly $1/3 > 1/4$: every independent set
has at most one vertex, and a one-vertex independent set exists.
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:k3} all distinct pairs are adjacent, so any independent
set has at most one vertex; thus $|S|/3 \le 1/3$. Conversely $\{p_0\}$ is
independent with $|S|/3 = 1/3$. Hence $\alpha(U(p))=1$ and $\rho(U(p))=1/3$.
\end{proof}

\section{Theorem versus Conjecture}

\begin{observation}
Theorem~\ref{thm:main} gives $\rho(G) \ge 1/\chi(G)$. To conclude
$\rho(G) \ge 1/4$ over a class via this route one needs $\chi(G) \le 4$
throughout, which fails for planar unit-distance graphs.
\end{observation}

\begin{observation}[de Grey, 2018]
There is an explicit finite planar point set whose unit-distance graph has
chromatic number at least $5$. Hence the chromatic number of the plane is at
least $5$, and no four-coloring argument covers all planar unit-distance graphs.
\end{observation}

\begin{consequence}
For a five-chromatic planar unit-distance graph the engine yields only
$\rho(G) \ge 1/5$. The best known rigorous lower bounds on the independence ratio
of the plane sit below $1/4$ (near $0.229$). Thus the unconditional planar
quarter claim is currently a conjecture, provable, if at all, by density or
packing arguments rather than colorability.
\end{consequence}

\section{Applications}

Lower bounds on the independence ratio guarantee conflict-free capacity: in
frequency assignment an independent set is an interference-free reuse pattern; in
scheduling and seating, simultaneously satisfiable demands; in sensor placement,
mutually non-jamming layouts. A four-coloring immediately certifies a
quarter-capacity guarantee via Theorem~\ref{thm:quarter}.

\section{Discussion and Future Work}

\textbf{The true planar infimum.} We conjecture the infimum of $\rho$ over finite
planar unit-distance graphs is a single constant strictly between $0.22$ and
$0.26$, in particular strictly below $1/4$; colorability provably cannot deliver
$1/4$, so the constant must be argued by packing/density, with the best
constructions near $0.229$.

\textbf{Sharpness is a coloring phenomenon.} We conjecture the bound $1/k$ is
attained by a planar unit-distance graph only when its largest clique is a
triangle, never by a $k$-color-critical planar family for $k \ge 4$: $K_k$
($k \ge 4$) is not planar-unit-distance realizable, forcing larger witnesses
strictly into the interior, as the triangle shows at $1/3$.

\textbf{An edge-count phase transition.} We conjecture that for such graphs on
$n$ vertices with $m$ edges, $\rho$ is bounded below by a quantity of order
$n/(m+n)$, overtaking any coloring bound in the sparse regime
$m = o(n^{4/3})$, the extremal edge count for planar unit distances.

