from __future__ import annotations
from fractions import Fraction
from typing import Dict, List, Set, Tuple

Graph = Dict[int, Set[int]]


def complete_graph(k: int) -> Graph:
    """The complete graph K_k as an adjacency-set map."""
    return {i: {j for j in range(k) if j != i} for i in range(k)}


def greedy_coloring(graph: Graph) -> Dict[int, int]:
    """A proper first-fit coloring with colors 0,1,2,..."""
    color: Dict[int, int] = {}
    for v in sorted(graph):
        used = {color[u] for u in graph[v] if u in color}
        c = 0
        while c in used:
            c += 1
        color[v] = c
    return color


def largest_color_class(graph: Graph) -> Tuple[int, List[int]]:
    """Return (#colors used, a largest color class) certifying n <= k*|S|."""
    color = greedy_coloring(graph)
    k = max(color.values()) + 1 if color else 0
    classes: Dict[int, List[int]] = {}
    for v, c in color.items():
        classes.setdefault(c, []).append(v)
    return k, max(classes.values(), key=len)


if __name__ == "__main__":
    for k in (2, 3, 4, 5):
        G = complete_graph(k)
        n = len(G)
        num_colors, cls = largest_color_class(G)
        assert n <= num_colors * len(cls)
        print(f"K_{k}: n={n}, class size={len(cls)}, "
              f"bound rho>=1/{num_colors}={Fraction(1,num_colors)}")

from __future__ import annotations
import itertools, math
from fractions import Fraction
from typing import Dict, List, Sequence, Set, Tuple

Point = Tuple[float, float]
Graph = Dict[int, Set[int]]


def unit_distance_graph(points: Sequence[Point], tol: float = 1e-9) -> Graph:
    """Join pairs of planar points whose distance is within tol of 1."""
    n = len(points)
    adj: Graph = {i: set() for i in range(n)}
    for i, j in itertools.combinations(range(n), 2):
        if abs(math.dist(points[i], points[j]) - 1.0) <= tol:
            adj[i].add(j); adj[j].add(i)
    return adj


def is_independent(graph: Graph, subset: Sequence[int]) -> bool:
    s = set(subset)
    return all(not (graph[u] & s - {u}) for u in s)


def independence_ratio(graph: Graph) -> Fraction:
    """Exact independence ratio by brute-force enumeration."""
    V = list(graph)
    for r in range(len(V), -1, -1):
        for sub in itertools.combinations(V, r):
            if is_independent(graph, sub):
                return Fraction(r, len(V))
    return Fraction(0)


if __name__ == "__main__":
    pts: List[Point] = [(0.0, 0.0), (1.0, 0.0), (0.5, math.sqrt(3) / 2)]
    G = unit_distance_graph(pts)
    rho = independence_ratio(G)
    print("Unit equilateral triangle is K_3; independence ratio =", rho)
    assert rho == Fraction(1, 3) and rho > Fraction(1, 4)

