    return (largest, k)

function ExactIndependenceRatio(graph):
    V <- vertices of graph;  n <- |V|
    if n = 0: return 0
    for r from n down to 0:
        for each subset S of V with |S| = r:
            if S is independent (no edge inside S):
                return r / n           # first, hence largest
    return 0

